package org.marketreview.nativeapp;
import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import org.json.*;
final class EvidenceReviewStore {
 final File file;
 EvidenceReviewStore(File file)throws Exception{EvidenceReviewModel.require(file!=null&&file.isAbsolute(),"复核库路径须为绝对路径");this.file=file;File dir=file.getParentFile();EvidenceReviewModel.require(dir.isDirectory()||dir.mkdirs(),"复核库目录不可用");try(SQLiteDatabase db=open()){db.beginTransaction();try{int v=db.getVersion(),a=scalar(db,"PRAGMA application_id");if(v==0&&a==0){EvidenceReviewModel.require(scalar(db,"SELECT count(*) FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name!='android_metadata'")==0,"目标非空，不重建");try(Cursor c=db.rawQuery("PRAGMA table_info(android_metadata)",null)){if(c.moveToFirst())EvidenceReviewModel.require(c.getInt(0)==0&&c.getString(1).equals("locale")&&c.getString(2).equalsIgnoreCase("TEXT")&&c.getInt(3)==0&&c.isNull(4)&&c.getInt(5)==0&&!c.moveToNext(),"android_metadata结构无效，不重建");}db.execSQL("CREATE TABLE records(kind TEXT NOT NULL,id TEXT NOT NULL,revision TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(kind,id))");db.execSQL("PRAGMA application_id="+0x45565231);db.setVersion(1);}else EvidenceReviewModel.require(a==0x45565231&&v==1,"复核库身份/版本不支持，不重建");try(Cursor c=db.rawQuery("PRAGMA table_info(records)",null)){String[] names={"kind","id","revision","payload"};int n=0;while(c.moveToNext()){EvidenceReviewModel.require(n<4&&c.getInt(0)==n&&c.getString(1).equals(names[n])&&c.getString(2).equalsIgnoreCase("TEXT")&&c.getInt(3)==1&&c.isNull(4)&&c.getInt(5)==(n<2?n+1:0),"复核库表结构不兼容，不重建");n++;}EvidenceReviewModel.require(n==4,"复核库表结构不完整");}EvidenceReviewModel.require(scalar(db,"SELECT count(*) FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name NOT IN ('records','android_metadata')")==0,"复核库含不兼容表，不重建");try(Cursor c=db.rawQuery("SELECT kind,id,revision,payload FROM records LIMIT 0",null)){c.moveToFirst();}db.setTransactionSuccessful();}finally{db.endTransaction();}}}
 SQLiteDatabase open(){return SQLiteDatabase.openDatabase(file.getAbsolutePath(),null,SQLiteDatabase.CREATE_IF_NECESSARY);}
 static int scalar(SQLiteDatabase db,String sql){try(Cursor c=db.rawQuery(sql,null)){EvidenceReviewModel.require(c.moveToFirst(),"复核库查询失败");return c.getInt(0);}}
 static JSONObject get(SQLiteDatabase db,String kind,String id)throws Exception{int chars,bytes;try(Cursor c=db.rawQuery("SELECT length(payload),length(CAST(payload AS BLOB)) FROM records WHERE kind=? AND id=?",new String[]{kind,id})){if(!c.moveToFirst())return new JSONObject();chars=c.getInt(0);bytes=c.getInt(1);}EvidenceReviewModel.require(bytes<=SourceAnalysisPacket.BYTE_LIMIT,"记录超过25MiB；未截断");StringBuilder out=new StringBuilder(chars);for(int start=1;start<=chars;start+=131072)try(Cursor c=db.rawQuery("SELECT substr(payload,?,131072) FROM records WHERE kind=? AND id=?",new String[]{Integer.toString(start),kind,id})){EvidenceReviewModel.require(c.moveToFirst(),"读取期间记录已变化");out.append(c.getString(0));}return new JSONObject(out.toString());}
 static JSONObject pure(JSONObject row)throws Exception{JSONObject r=SourceAnalysisPacket.copy(row);r.remove("recordRevision");return r;}
 static void insert(SQLiteDatabase db,JSONObject row)throws Exception{if(row.optString("recordRevision").isEmpty())row.put("recordRevision",UUID.randomUUID().toString());ContentValues v=new ContentValues();v.put("kind",row.getString("kind"));v.put("id",row.getString("id"));v.put("revision",row.getString("recordRevision"));v.put("payload",EvidenceReviewModel.json(row));db.insertOrThrow("records",null,v);}
 JSONObject get(String kind,String id)throws Exception{try(SQLiteDatabase db=open()){db.beginTransaction();try{JSONObject r=get(db,kind,id);db.setTransactionSuccessful();return r;}finally{db.endTransaction();}}}
 JSONArray list(String kind,int offset)throws Exception{EvidenceReviewModel.require(offset>=0,"分页无效");JSONArray out=new JSONArray();try(SQLiteDatabase db=open();Cursor c=db.rawQuery("SELECT id FROM records WHERE kind=? ORDER BY rowid DESC LIMIT 50 OFFSET ?",new String[]{kind,Integer.toString(offset)})){while(c.moveToNext()){JSONObject r=get(db,kind,c.getString(0)),meta=new JSONObject();for(String k:new String[]{"kind","id","title","reportId","approvedAt","recordRevision"})if(r.has(k))meta.put(k,r.get(k));meta.put("candidateCount",EvidenceReviewModel.arr(r,"candidates").length());out.put(meta);}}return out;}
 JSONObject put(JSONObject input,String expected)throws Exception{JSONObject r=EvidenceReviewModel.validate(SourceAnalysisPacket.copy(input));String kind=r.getString("kind"),id=r.getString("id");EvidenceReviewModel.require(kind.equals("drafts")||kind.equals("previews")||kind.equals("bindings"),"报告/候选只能明确合并/确认");try(SQLiteDatabase db=open()){db.beginTransaction();try{EvidenceReviewModel.require(get(db,kind,id).optString("recordRevision").equals(expected),"另一入口已更新；未覆盖旧草稿");r.put("recordRevision",UUID.randomUUID().toString());db.delete("records","kind=? AND id=?",new String[]{kind,id});insert(db,r);db.setTransactionSuccessful();return r;}finally{db.endTransaction();}}}
 JSONObject preview(String input)throws Exception{JSONArray incoming=EvidenceReviewModel.decode(input),rows=new JSONArray();int added=0,duplicate=0,conflict=0;try(SQLiteDatabase db=open()){db.beginTransaction();try{for(int i=0;i<incoming.length();i++){JSONObject r=incoming.getJSONObject(i),old=get(db,r.getString("kind"),r.getString("id"));String state=old.length()==0?"new":EvidenceReviewModel.json(pure(old)).equals(EvidenceReviewModel.json(pure(r)))?"duplicate":"conflict";if(state.equals("new"))added++;else if(state.equals("duplicate"))duplicate++;else conflict++;rows.put(new JSONObject().put("record",r).put("state",state));}db.setTransactionSuccessful();}finally{db.endTransaction();}}return new JSONObject().put("schema","evidence-review-preview-v1").put("rows",rows).put("newCount",added).put("duplicateCount",duplicate).put("conflictCount",conflict);}
 JSONObject stage(JSONObject preview,String expected)throws Exception{return put(new JSONObject().put("kind","previews").put("id","import-preview").put("preview",preview),expected);}
 JSONObject merge(JSONObject preview,String revision)throws Exception{EvidenceReviewModel.require(preview.optString("schema").equals("evidence-review-preview-v1")&&preview.optJSONArray("rows")!=null,"请先预览");int added=0,duplicate=0,conflict=0;String next="";try(SQLiteDatabase db=open()){db.beginTransaction();try{if(!revision.isEmpty()){JSONObject staged=get(db,"previews","import-preview");EvidenceReviewModel.require(staged.optString("recordRevision").equals(revision)&&EvidenceReviewModel.json(EvidenceReviewModel.obj(staged,"preview")).equals(EvidenceReviewModel.json(preview)),"预览被另一入口更新，未合并");}JSONArray rows=preview.getJSONArray("rows");for(int i=0;i<rows.length();i++){JSONObject r=EvidenceReviewModel.validate(SourceAnalysisPacket.copy(rows.getJSONObject(i).getJSONObject("record")));EvidenceReviewModel.require(!r.getString("kind").equals("previews")&&!r.getString("kind").equals("drafts"),"待确认材料不可当作证据合并");JSONObject old=get(db,r.getString("kind"),r.getString("id"));if(old.length()>0){if(EvidenceReviewModel.json(pure(old)).equals(EvidenceReviewModel.json(pure(r))))duplicate++;else conflict++;continue;}insert(db,r);added++;}if(!revision.isEmpty()){next=UUID.randomUUID().toString();db.delete("records","kind='previews' AND id='import-preview'",null);insert(db,new JSONObject().put("kind","previews").put("id","import-preview").put("preview",new JSONObject()).put("recordRevision",next));}db.setTransactionSuccessful();}finally{db.endTransaction();}}return new JSONObject().put("added",added).put("duplicate",duplicate).put("conflict",conflict).put("previewRevision",next);}
 JSONObject approve(String reportId,JSONArray input,boolean acknowledged,JSONArray catalogue)throws Exception{EvidenceReviewModel.require(acknowledged&&input.length()>0,"请选择候选并确认材料尚未独立验证");try(SQLiteDatabase db=open()){db.beginTransaction();try{JSONObject report=EvidenceReviewModel.validate(get(db,"reports",reportId));JSONArray selected=new JSONArray(),candidates=report.getJSONArray("candidates");Set<String> ids=new HashSet<>();for(int i=0;i<input.length();i++){JSONObject r=input.getJSONObject(i);int index=r.optInt("row",-1);EvidenceReviewModel.require(index>=0&&index<candidates.length(),"候选行不存在");JSONObject audited=EvidenceReviewModel.audit(candidates.getJSONObject(index),r.getString("instrumentId"),catalogue);EvidenceReviewModel.require(EvidenceReviewModel.json(audited).equals(EvidenceReviewModel.json(r))&&r.optString("identityState").equals("exact"),"身份/名称尚未精确核验，不能确认");EvidenceReviewModel.require(ids.add(r.getString("instrumentId")),"所选完整身份重复，请人工取舍");selected.put(r);}try(Cursor c=db.rawQuery("SELECT id FROM records WHERE kind='batches'",null)){while(c.moveToNext()){JSONObject old=get(db,"batches",c.getString(0));if(!old.optString("reportId").equals(reportId))continue;JSONArray a=old.getJSONArray("candidates");for(int i=0;i<a.length();i++)EvidenceReviewModel.require(!ids.contains(a.getJSONObject(i).getString("instrumentId")),"此报告已有该完整身份候选；未重复保存");}}JSONObject row=new JSONObject().put("kind","batches").put("id","batch:"+SourceAnalysisPacket.hash(reportId+EvidenceReviewModel.fingerprint(selected))).put("reportId",reportId).put("title",report.getString("title")).put("reportSnapshot",pure(report)).put("candidates",selected).put("approvedAt",Instant.now().toString()).put("verification","manual-unverified").put("acknowledged",true);EvidenceReviewModel.validate(row);insert(db,row);db.setTransactionSuccessful();return row;}finally{db.endTransaction();}}}
 byte[] backup()throws Exception{JSONArray rows=new JSONArray();long size=0;try(SQLiteDatabase db=open();Cursor c=db.rawQuery("SELECT kind,id,length(CAST(payload AS BLOB)) FROM records WHERE kind NOT IN ('previews','drafts') ORDER BY kind,id",null)){while(c.moveToNext()){size+=c.getLong(2);EvidenceReviewModel.require(size<=SourceAnalysisPacket.BYTE_LIMIT,"备份超过25MiB；未截断");rows.put(get(db,c.getString(0),c.getString(1)));}}return EvidenceReviewModel.json(new JSONObject().put("schema","evidence-review-v1").put("records",rows).put("mergePolicy","keep-existing")).getBytes(StandardCharsets.UTF_8);}
}


